617	package net.officefloor.hq.app.setting;
618	
619	import jakarta.validation.Valid;
620	import java.math.BigDecimal;
621	import java.time.LocalDate;
622	import java.time.format.DateTimeParseException;
623	import java.util.LinkedHashMap;
624	import java.util.Map;
625	import java.util.Set;
626	import java.util.regex.Pattern;
627	import net.officefloor.plugin.variable.Out;
628	import org.springframework.web.bind.annotation.RequestBody;
629	
630	public class ValidateSettingsRequest {
631	
632	    /** 0.00 or more, with at most two decimals. */
633	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?|\\.\\d{1,2}");
634	
635	    /** A percent: 0.00 or more, with at most two decimals. */
636	    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
637	
638	    /** The grades terms can be set for. */
639	    private static final Set<String> GRADES = Set.of("A", "B", "C");
640	
641	    /** 0 or more whole days. */
642	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
643	
644	    public void validate(@RequestBody @Valid SettingsRequest request, Out<ClerkLimit> limit, Out<Floor> floor,
645	            Out<Terms> terms, Out<LatePct> latePct, Out<PolicyDate> policyDate,
646	            Out<PeriodNumberingFrom> periodNumberingFrom, Out<GradeTerms> gradeTerms)
647	            throws InvalidSettingException {
648	        limit.set(clerkLimit(request.clerkLimit()));
649	        floor.set(floor(request.floor()));
650	        terms.set(terms(request.terms()));
651	        latePct.set(latePct(request.latePct()));
652	        policyDate.set(policyDate(request.policyDate()));
653	        periodNumberingFrom.set(periodNumberingFrom(request.periodNumberingFrom()));
654	        gradeTerms.set(gradeTerms(request.gradeTerms()));
655	    }
656	
657	    private static ClerkLimit clerkLimit(String requested) throws InvalidSettingException {
658	        if (requested == null) {
659	            return new ClerkLimit(false, null);
660	        }
661	        String value = requested.trim();
662	        if (value.isEmpty()) {
663	            return new ClerkLimit(true, null);
664	        }
665	        if (!AMOUNT.matcher(value).matches()) {
666	            throw new InvalidSettingException("The clerk limit must be 0.00 or more, with at most two decimals, or blank.");
667	        }
668	        return new ClerkLimit(true, new BigDecimal(value).setScale(2));
669	    }
670	
671	    private static Terms terms(String requested) throws InvalidSettingException {
672	        if (requested == null) {
673	            return new Terms(null);
674	        }
675	        String value = requested.trim();
676	        if (value.isEmpty()) {
677	            return new Terms(SettingRepository.DEFAULT_TERMS);
678	        }
679	        if (!DAYS.matcher(value).matches()) {
680	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more, or blank.");
681	        }
682	        return new Terms(Integer.parseInt(value));
683	    }
684	
685	    private static GradeTerms gradeTerms(Map<String, String> requested) throws InvalidSettingException {
686	        Map<String, Integer> terms = new LinkedHashMap<>();
687	        if (requested == null) {
688	            return new GradeTerms(terms);
689	        }
690	        for (String grade : requested.keySet().stream().sorted().toList()) {
691	            if (!GRADES.contains(grade)) {
692	                throw new InvalidSettingException("Terms can only be set for grade A, B or C.");
693	            }
694	            String value = requested.get(grade) == null ? "" : requested.get(grade).trim();
695	            if (value.isEmpty()) {
696	                terms.put(grade, null);
697	            } else if (!DAYS.matcher(value).matches()) {
698	                throw new InvalidSettingException("The terms for a grade must be a whole number of days, 0 or more, or blank.");
699	            } else {
700	                terms.put(grade, Integer.parseInt(value));
701	            }
702	        }
703	        return new GradeTerms(terms);
